            >
                <span className={`w-1.5 h-1.5 rounded-full ${status === 'USER' ? 'bg-veritas-gold animate-pulse' : 'bg-zinc-600'}`}></span>
                {status === 'USER' ? 'SUB_LINK' : 'SYS_LINK'}
            </button>
        </Tooltip>

        {showModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">
                <div className="w-full max-w-md bg-zinc-950 border border-zinc-800 shadow-[0_0_50px_rgba(0,0,0,0.8)] p-6 relative">
                    {/* Decorators */}
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-veritas-gold via-veritas-cyan to-veritas-gold opacity-50"></div>
                    <div className="absolute -bottom-1 -right-1 w-4 h-4 border-r border-b border-zinc-700"></div>
                    <div className="absolute -top-1 -left-1 w-4 h-4 border-l border-t border-zinc-700"></div>

                    <h3 className="text-white font-mono text-lg font-bold mb-4 flex items-center gap-2 tracking-widest">
                        <span className="text-veritas-gold">✦</span> ESTABLISH UPLINK
                    </h3>

                    <p className="text-zinc-400 text-xs font-mono leading-relaxed mb-6">
                        Override system defaults to utilize your personal <span className="text-zinc-200">Google Cloud Subscription</span>.
                        <br/><br/>
                        This enables high-fidelity reasoning models (Gemini Advanced) under your own usage limits.
                    </p>

                    <div className="bg-zinc-900/50 border border-zinc-800 p-3 mb-6 hover:border-veritas-cyan/30 transition-colors">
                        <a 
                            href="https://ai.google.dev/gemini-api/docs/billing" 
