                            <span className="text-zinc-600 group-hover:text-veritas-cyan transform group-hover:translate-x-1 transition-all">↗</span>
                        </a>
                    </div>

                    <div className="flex gap-3 justify-end items-center">
                        <button 
                            onClick={() => setShowModal(false)}
