import React, { useState, useEffect } from 'react';
import { Tooltip } from '../../../components/Tooltip';

interface AuthBadgeProps {
    manualApiKey: string | null;
    onSetManualKey: (key: string | null) => void;
}

type AuthStatus = 'SYSTEM' | 'SUBSCRIPTION' | 'MANUAL';

export const AuthBadge: React.FC<AuthBadgeProps> = ({ manualApiKey, onSetManualKey }) => {
  const [hasSubscription, setHasSubscription] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [inputKey, setInputKey] = useState('');

  // Determine current effective status
  const currentStatus: AuthStatus = manualApiKey ? 'MANUAL' : (hasSubscription ? 'SUBSCRIPTION' : 'SYSTEM');

  useEffect(() => {
    const checkSupport = async () => {
        const aiStudio = (window as any).aistudio;
        if (aiStudio) {
            try {
                const hasKey = await aiStudio.hasSelectedApiKey();
                setHasSubscription(hasKey);
            } catch (e) {
                console.warn("AI Studio check failed", e);
            }
        }
    };
    checkSupport();
  }, []);

  const handleSubscriptionConnect = async () => {
    const aiStudio = (window as any).aistudio;
    if (!aiStudio) return;

    try {
        await aiStudio.openSelectKey();
        setHasSubscription(true);
        // If they select subscription, we clear the manual key to ensure subscription takes precedence? 
        // Or vice versa? The prompt implies choice. 
        // We will clear manual key if they explicitly connect subscription to avoid confusion.
        onSetManualKey(null); 
        setShowModal(false);
    } catch (e: any) {
        console.error("Key Selection Failed", e);
        if (e.message && e.message.includes("Requested entity was not found")) {
            setHasSubscription(false);
            setTimeout(() => setShowModal(true), 500);
        }
    }
  };

  const handleManualSubmit = () => {
      if (inputKey.trim()) {
          onSetManualKey(inputKey.trim());
          setHasSubscription(false); // Manual overrides subscription visually
          setShowModal(false);
          setInputKey('');
      }
  };

  const handleReset = () => {
      onSetManualKey(null);
      setHasSubscription(false);
      // We can't easily "disconnect" AI studio subscription via API, but we can visually reset state
      // and rely on System env if available.
      setShowModal(false);
  };

  const renderBadge = () => {
      if (currentStatus === 'MANUAL') {
          return (
             <div className="flex items-center gap-2 text-veritas-red border border-veritas-red bg-veritas-red/10 px-3 py-1 text-[10px] font-mono shadow-[0_0_10px_rgba(255,42,42,0.2)]">
                <span className="w-1.5 h-1.5 rounded-full bg-veritas-red animate-pulse"></span>
                MANUAL_KEY
             </div>
          );
      }
      if (currentStatus === 'SUBSCRIPTION') {
          return (
             <div className="flex items-center gap-2 text-veritas-gold border border-veritas-gold bg-veritas-gold/10 px-3 py-1 text-[10px] font-mono shadow-[0_0_10px_rgba(255,204,0,0.2)]">
                <span className="w-1.5 h-1.5 rounded-full bg-veritas-gold animate-pulse"></span>
                SUB_LINK
             </div>
          );
      }
      return (
         <div className="flex items-center gap-2 text-zinc-500 border border-zinc-800 hover:text-white hover:border-zinc-600 px-3 py-1 text-[10px] font-mono transition-colors">
            <span className="w-1.5 h-1.5 rounded-full bg-zinc-600"></span>
            SYS_LINK
         </div>
      );
  };

  return (
    <>
        <Tooltip content={`Authentication Mode: ${currentStatus}`} position="bottom">
            <button onClick={() => setShowModal(true)}>
                {renderBadge()}
            </button>
        </Tooltip>

        {showModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-in fade-in duration-200">
                <div className="w-full max-w-2xl bg-zinc-950 border border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,0.9)] relative grid md:grid-cols-2">

                    {/* Header Absolute */}
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-veritas-gold via-veritas-cyan to-veritas-red opacity-50"></div>
                    <button 
                        onClick={() => setShowModal(false)}
                        className="absolute top-2 right-2 text-zinc-500 hover:text-white px-2 z-10 font-mono"
                    >
                        ✕
                    </button>

                    {/* COL 1: GOOGLE SUBSCRIPTION */}
                    <div className="p-8 border-b md:border-b-0 md:border-r border-zinc-800 flex flex-col items-center text-center relative overflow-hidden group">
                        <div className="absolute inset-0 bg-veritas-gold/5 group-hover:bg-veritas-gold/10 transition-colors"></div>

                        <div className="w-12 h-12 rounded-full bg-veritas-gold/20 text-veritas-gold flex items-center justify-center text-xl mb-4 border border-veritas-gold/50 shadow-[0_0_20px_rgba(255,204,0,0.2)]">
                            ✦
                        </div>
                        <h3 className="text-white font-mono font-bold tracking-widest mb-2">SUBSCRIPTION UPLINK</h3>
                        <p className="text-[10px] text-zinc-400 leading-relaxed mb-6 font-mono">
                            Authenticate via Google Cloud. Usage is billed to your personal project. Recommended for high-limit access.
                        </p>

                        <button 
                            onClick={handleSubscriptionConnect}
                            className="mt-auto w-full py-3 bg-veritas-gold text-black font-bold font-mono text-xs uppercase tracking-wider hover:bg-white transition-colors"
                        >
                            CONNECT ACCOUNT
                        </button>
                    </div>

                    {/* COL 2: MANUAL KEY */}
                    <div className="p-8 flex flex-col items-center text-center relative overflow-hidden group">
                        <div className="absolute inset-0 bg-veritas-red/5 group-hover:bg-veritas-red/10 transition-colors"></div>

                        <div className="w-12 h-12 rounded-full bg-veritas-red/20 text-veritas-red flex items-center justify-center text-xl mb-4 border border-veritas-red/50 shadow-[0_0_20px_rgba(255,42,42,0.2)]">
                            ⚡
                        </div>
                        <h3 className="text-white font-mono font-bold tracking-widest mb-2">MANUAL OVERRIDE</h3>
                        <p className="text-[10px] text-zinc-400 leading-relaxed mb-6 font-mono">
                            Directly inject a raw API Key. Bypasses system defaults. Use for custom enterprise keys.
                        </p>

                        <input 
                            type="password"
                            value={inputKey}
                            onChange={(e) => setInputKey(e.target.value)}
                            placeholder="AIzaSy..."
                            className="w-full bg-black/50 border border-zinc-700 text-white font-mono text-xs p-2 mb-3 focus:border-veritas-red focus:outline-none text-center"
                        />

                        <button 
                            onClick={handleManualSubmit}
                            disabled={!inputKey}
                            className="w-full py-3 border border-veritas-red text-veritas-red font-bold font-mono text-xs uppercase tracking-wider hover:bg-veritas-red hover:text-black transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            INJECT KEY
                        </button>
                    </div>

                    {/* FOOTER: RESET */}
                    {(currentStatus !== 'SYSTEM') && (
                        <div className="col-span-1 md:col-span-2 border-t border-zinc-800 p-2 bg-zinc-900/50 text-center">
                            <button 
                                onClick={handleReset}
                                className="text-[9px] text-zinc-500 hover:text-white font-mono uppercase tracking-widest"
                            >
                                RESET TO SYSTEM DEFAULTS
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { Tooltip } from '../../../components/Tooltip';

interface AuthBadgeProps {
    manualApiKey: string | null;
    onSetManualKey: (key: string | null) => void;
}

type AuthStatus = 'SYSTEM' | 'SUBSCRIPTION' | 'MANUAL';

export const AuthBadge: React.FC<AuthBadgeProps> = ({ manualApiKey, onSetManualKey }) => {
  const [hasSubscription, setHasSubscription] = useState(false);
  const [isAiStudioAvailable, setIsAiStudioAvailable] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [inputKey, setInputKey] = useState('');

  // Determine current effective status
  // If manual key is present, it overrides everything.
  // If no manual key, we check if subscription is active.
  const currentStatus: AuthStatus = manualApiKey ? 'MANUAL' : (hasSubscription ? 'SUBSCRIPTION' : 'SYSTEM');

  useEffect(() => {
    const checkSupport = async () => {
        const aiStudio = (window as any).aistudio;
        if (aiStudio) {
            setIsAiStudioAvailable(true);
            try {
                const hasKey = await aiStudio.hasSelectedApiKey();
                setHasSubscription(hasKey);
            } catch (e) {
                console.warn("AI Studio check failed", e);
            }
        }
    };
    checkSupport();
  }, []);

  const handleSubscriptionConnect = async () => {
    const aiStudio = (window as any).aistudio;
    if (!aiStudio) return;

    try {
        await aiStudio.openSelectKey();
        // We assume success if the promise resolves
        setHasSubscription(true);
        onSetManualKey(null); // Clear manual key to ensure subscription takes priority
        setShowModal(false);
    } catch (e: any) {
        console.error("Key Selection Failed", e);
        if (e.message && e.message.includes("Requested entity was not found")) {
            setHasSubscription(false);
            // Re-open modal to allow retry if they cancelled out of the Google flow weirdly
            setTimeout(() => setShowModal(true), 500);
        }
    }
  };

  const handleManualSubmit = () => {
      if (inputKey.trim()) {
          onSetManualKey(inputKey.trim());
          setHasSubscription(false); // Manual overrides subscription
          setShowModal(false);
          setInputKey('');
      }
  };

  const handleReset = () => {
      onSetManualKey(null);
      setHasSubscription(false);
      setShowModal(false);
  };

  const renderBadge = () => {
      if (currentStatus === 'MANUAL') {
          return (
             <div className="flex items-center gap-2 text-veritas-red border border-veritas-red bg-veritas-red/10 px-3 py-1 text-[10px] font-mono shadow-[0_0_10px_rgba(255,42,42,0.2)] hover:bg-veritas-red/20 transition-all">
                <span className="w-1.5 h-1.5 rounded-full bg-veritas-red animate-pulse"></span>
                MANUAL_KEY
             </div>
          );
      }
      if (currentStatus === 'SUBSCRIPTION') {
          return (
             <div className="flex items-center gap-2 text-veritas-gold border border-veritas-gold bg-veritas-gold/10 px-3 py-1 text-[10px] font-mono shadow-[0_0_10px_rgba(255,204,0,0.2)] hover:bg-veritas-gold/20 transition-all">
                <span className="w-1.5 h-1.5 rounded-full bg-veritas-gold animate-pulse"></span>
                GOOGLE_SUB
             </div>
          );
      }
      return (
         <div className="flex items-center gap-2 text-zinc-500 border border-zinc-800 hover:text-white hover:border-zinc-600 px-3 py-1 text-[10px] font-mono transition-colors">
            <span className="w-1.5 h-1.5 rounded-full bg-zinc-600"></span>
            SYS_LINK
         </div>
      );
  };

  return (
    <>
        <Tooltip content={`Authentication Source: ${currentStatus}`} position="bottom">
            <button onClick={() => setShowModal(true)}>
                {renderBadge()}
            </button>
        </Tooltip>

        {showModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4 animate-in fade-in duration-200">
                <div className="w-full max-w-3xl bg-zinc-950 border border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,0.9)] relative grid md:grid-cols-2">

                    {/* Header Absolute */}
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-veritas-gold via-veritas-cyan to-veritas-red opacity-50"></div>
                    <button 
                        onClick={() => setShowModal(false)}
                        className="absolute top-2 right-2 text-zinc-500 hover:text-white px-2 z-10 font-mono"
                    >
                        ✕
                    </button>

                    {/* COL 1: GOOGLE SUBSCRIPTION */}
                    <div className={`p-8 border-b md:border-b-0 md:border-r border-zinc-800 flex flex-col items-center text-center relative overflow-hidden group transition-all ${!isAiStudioAvailable ? 'opacity-50 grayscale' : ''}`}>
                        <div className="absolute inset-0 bg-veritas-gold/5 group-hover:bg-veritas-gold/10 transition-colors"></div>

                        {/* Google G Icon approximation */}
                        <div className="w-12 h-12 rounded-full bg-white text-black flex items-center justify-center text-xl mb-4 shadow-[0_0_20px_rgba(255,255,255,0.2)] font-bold">
                            G
                        </div>
                        <h3 className="text-white font-mono font-bold tracking-widest mb-2">GOOGLE SUBSCRIPTION</h3>
                        <p className="text-[10px] text-zinc-400 leading-relaxed mb-6 font-mono h-12">
                            Authenticate using your Google Cloud Project billing. <br/>
                            <span className="text-veritas-gold">Recommended for high usage limits.</span>
                        </p>

                        {isAiStudioAvailable ? (
                            <button 
                                onClick={handleSubscriptionConnect}
                                className="mt-auto w-full py-3 bg-white text-black font-bold font-mono text-xs uppercase tracking-wider hover:bg-veritas-gold hover:text-black transition-colors shadow-[0_0_15px_rgba(255,255,255,0.3)]"
                            >
                                {hasSubscription ? 'SWITCH ACCOUNT' : 'CONNECT SUBSCRIPTION'}
                            </button>
                        ) : (
                            <div className="mt-auto w-full py-3 border border-zinc-800 text-zinc-600 font-mono text-[10px] uppercase cursor-not-allowed">
                                ENVIRONMENT UNAVAILABLE
                            </div>
                        )}

                        {!isAiStudioAvailable && (
                            <p className="text-[9px] text-zinc-600 mt-2">Only available in AI Studio / IDX environments</p>
                        )}
                    </div>

                    {/* COL 2: MANUAL KEY */}
                    <div className="p-8 flex flex-col items-center text-center relative overflow-hidden group">
                        <div className="absolute inset-0 bg-veritas-red/5 group-hover:bg-veritas-red/10 transition-colors"></div>

                        <div className="w-12 h-12 rounded-full bg-veritas-red/20 text-veritas-red flex items-center justify-center text-xl mb-4 border border-veritas-red/50 shadow-[0_0_20px_rgba(255,42,42,0.2)]">
                            ⚡
                        </div>
                        <h3 className="text-white font-mono font-bold tracking-widest mb-2">MANUAL API KEY</h3>
                        <p className="text-[10px] text-zinc-400 leading-relaxed mb-6 font-mono h-12">
                            Enter a raw Google Gemini API key directly.<br/>
                            <span className="text-veritas-red">Bypasses subscription check.</span>
                        </p>

                        <input 
                            type="password"
                            value={inputKey}
                            onChange={(e) => setInputKey(e.target.value)}
                            placeholder="AIzaSy..."
                            className="w-full bg-black/50 border border-zinc-700 text-white font-mono text-xs p-3 mb-3 focus:border-veritas-red focus:outline-none text-center rounded-sm placeholder:text-zinc-700"
                        />

                        <button 
                            onClick={handleManualSubmit}
                            disabled={!inputKey}
                            className="w-full py-3 border border-veritas-red text-veritas-red font-bold font-mono text-xs uppercase tracking-wider hover:bg-veritas-red hover:text-black transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            USE MANUAL KEY
                        </button>
                    </div>

                    {/* FOOTER: RESET */}
                    {(manualApiKey || hasSubscription) && (
                        <div className="col-span-1 md:col-span-2 border-t border-zinc-800 p-3 bg-zinc-900/50 text-center flex justify-center">
                            <button 
                                onClick={handleReset}
                                className="text-[10px] text-zinc-500 hover:text-white font-mono uppercase tracking-widest border-b border-transparent hover:border-zinc-500 transition-all"
                            >
                                DISCONNECT & RETURN TO SYSTEM DEFAULT
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </>
  );
};

import { useState, useCallback, useRef } from 'react';
import { SystemConfig, LogEntry, ProcessState, ChatHistoryItem, AgentConfig } from '../types';
import { MultiAgentService } from '../services/geminiService';

const uuid = () => Math.random().toString(36).substring(2, 9);

export const useReasoningEngine = (config: SystemConfig, manualApiKey: string | null) => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [processState, setProcessState] = useState<ProcessState>(ProcessState.IDLE);
  const [activeAgentName, setActiveAgentName] = useState<string | null>(null);
  const [finalResult, setFinalResult] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatHistoryItem[]>([]);
  const [currentRound, setCurrentRound] = useState<number>(0);

  // Helper to add logs efficiently
  const addLog = useCallback((log: LogEntry) => {
      setLogs(prev => {
          const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
          return [...filtered, log];
      });
  }, []);

  const addWorkflowLog = useCallback((log: LogEntry) => {
      setLogs(prev => {
          const filtered = prev.filter(l => !(l.agentName === log.agentName && l.isThinking));
          return [...filtered, log];
      });
  }, []);

  // --- SUB-HANDLERS ---

  const handleInterrogation = async (
      service: MultiAgentService, 
      targetAgent: AgentConfig, 
      query: string, 
      chatHistory: ChatHistoryItem[]
  ) => {
      setProcessState(ProcessState.INTERROGATION);
      setActiveAgentName(targetAgent.name);

      const result = await service.runAgentInspection(
          targetAgent,
          query,
          config,
          chatHistory,
          addLog
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);
      setActiveAgentName(null);
  };

  const handleWorkflow = async (
      service: MultiAgentService,
      userPrompt: string,
      chatHistory: ChatHistoryItem[]
  ) => {
      setProcessState(ProcessState.WORKFLOW_RUNNING);

      const result = await service.runCustomChain(
          userPrompt,
          config,
          chatHistory,
          (log) => {
              addWorkflowLog(log);
              if (log.isThinking) setActiveAgentName(log.agentName);
          }
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);
      setActiveAgentName(null);

      const verdictLog: LogEntry = {
          id: uuid(),
          agentRole: 'verdict',
          agentName: 'WORKFLOW_COMPLETE',
          content: result,
          timestamp: Date.now()
      };
      setLogs(prev => [...prev, verdictLog]);

      setChatHistory(prev => [
        ...prev,
        { role: 'user', content: userPrompt },
        { role: 'model', content: result }
      ]);
  };

  const handleStandardDebate = async (
      service: MultiAgentService,
      userPrompt: string,
      chatHistory: ChatHistoryItem[]
  ) => {
      const result = await service.runReasoningChain(
        userPrompt, 
        config, 
        chatHistory,
        (log) => {
          addLog(log);
          if (log.isThinking) {
             setActiveAgentName(log.agentName);
             const stateMap: Record<string, ProcessState> = {
               'analyst': ProcessState.ANALYZING,
               'skeptic': ProcessState.AUDITING,
               'judge': ProcessState.JUDGING,
               'validator': ProcessState.VALIDATING
             };
             if (stateMap[log.agentRole]) setProcessState(stateMap[log.agentRole]);
          }
        },
        (round) => setCurrentRound(round)
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);
      setActiveAgentName(null);

      const verdictLog: LogEntry = {
          id: uuid(),
          agentRole: 'verdict',
          agentName: 'VERITAS_FINAL',
          content: result,
          timestamp: Date.now()
      };
      setLogs(prev => [...prev, verdictLog]);

      setChatHistory(prev => [
        ...prev,
        { role: 'user', content: userPrompt },
        { role: 'model', content: result }
      ]);
  };

  // --- MAIN ENTRY POINT ---

  const startReasoning = useCallback(async (userPrompt: string) => {
    // RESOLVE AUTH METHOD
    // 1. Manual Key
    // 2. Process Env (which handles Subscription injection automatically)
    const apiKey = manualApiKey || process.env.API_KEY;

    // Determine Auth Mode for Logging
    const authSource = manualApiKey ? 'MANUAL_OVERRIDE' : (process.env.API_KEY ? 'SUBSCRIPTION_UPLINK' : 'UNKNOWN_SOURCE');

    if (!apiKey) {
      console.error("API Key missing");
      setLogs(prev => [...prev, {
        id: 'ERR_KEY', 
        agentRole: 'system', 
        agentName: 'SYSTEM', 
        content: 'AUTHENTICATION ERROR: No Uplink Detected.\nPlease Connect Google Subscription or Enter API Key.', 
        timestamp: Date.now()
      }]);
      return;
    }

    setProcessState(ProcessState.ANALYZING);
    setFinalResult(null);
    setCurrentRound(0);
    setActiveAgentName(null);

    // Initial User Log
    const userLog: LogEntry = {
        id: uuid(),
        agentRole: 'user',
        agentName: 'OPERATOR',
        content: userPrompt,
        timestamp: Date.now()
    };

    setLogs(prev => {
        const newLogs = [...prev];
        if (prev.length > 0) {
           newLogs.push({
             id: `sep-${Date.now()}`,
             agentRole: 'system',
             agentName: 'SYSTEM', 
             content: `NEW_CYCLE_INITIATED [AUTH: ${authSource}]`,
             timestamp: Date.now()
           });
        } else {
             newLogs.push({
             id: `boot-${Date.now()}`,
             agentRole: 'system',
             agentName: 'SYSTEM', 
             content: `VERITAS KERNEL ONLINE [AUTH: ${authSource}]`,
             timestamp: Date.now()
           });
        }
        return [...newLogs, userLog];
    });

    const service = new MultiAgentService(apiKey);

    try {
      // 1. Interrogation Check
      const interrogationMatch = userPrompt.match(/^@([\w_]+):\s*(.+)/i);
      if (interrogationMatch) {
         const targetName = interrogationMatch[1];
         const query = interrogationMatch[2];
         const targetAgent = config.agents.find(a => 
             a.name.toLowerCase() === targetName.toLowerCase() || 
             a.role.toLowerCase() === targetName.toLowerCase()
         );

         if (targetAgent) {
             await handleInterrogation(service, targetAgent, query, chatHistory);
             return;
         }
      }

      // 2. Custom Workflow Check
      if (config.workflow && config.workflow.length > 0) {
          await handleWorkflow(service, userPrompt, chatHistory);
          return;
      }

      // 3. Standard Debate
      await handleStandardDebate(service, userPrompt, chatHistory);

    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setActiveAgentName(null);
      setLogs(prev => [...prev, {
        id: 'ERR', 
        agentRole: 'judge', 
        agentName: 'SYSTEM', 
        content: 'CRITICAL FAILURE: ' + (e as Error).message, 
        timestamp: Date.now()
      }]);
    }
  }, [config, chatHistory, addLog, addWorkflowLog, manualApiKey]);

  const clearMemory = useCallback(() => {
    setChatHistory([]);
    setLogs([]);
    setFinalResult(null);
    setProcessState(ProcessState.IDLE);
    setCurrentRound(0);
    setActiveAgentName(null);
  }, []);

  return {
    logs,
    processState,
    activeAgentName,
    finalResult,
    chatHistory,
    currentRound,
    startReasoning,
    clearMemory
  };
};
